function gamePulsePage(){
  const items = pulseData.items || [];
  const newItems = items.filter(item=>item.kind==='new');
  const hotItems = items.filter(item=>item.kind==='hot');
  const videosWithStats = items.filter(item=>item.video?.type==='video' && (item.video.views || item.video.likes)).length;
  const body=`${pageHero('DAILY PLAYER BRIEFING','Game Pulse: new releases and hot games','Six useful game briefings refreshed automatically: three newly released US iOS games and three current US iOS grossing leaders, each with an introduction, play pattern, practical tips, artwork and a creator-video path.',[[String(newItems.length),'new games'],[String(hotItems.length),'hot games'],['Daily','new edition']])}<section class="shell pulse-page"><div class="platform-warning"><b>Platform scope: US iOS/iPadOS</b><span>The hot signal is Apple grossing rank. It is not a Google Play chart or an editorial popularity score.</span></div><div class="live-status"><span><i></i>Daily edition ${esc(pulseData.date)} · generated ${esc(pulseTime)}</span><a href="${href('/about/sources/')}">How this feed is made →</a></div><div class="pulse-controls"><label for="pulse-search"><span>Search today’s briefings</span><input id="pulse-search" type="search" placeholder="Game, genre, developer or tip" autocomplete="off" data-pulse-search></label><div role="group" aria-label="Filter Game Pulse"><button class="selected" type="button" data-pulse-filter="all">All ${items.length}</button><button type="button" data-pulse-filter="new">New ${newItems.length}</button><button type="button" data-pulse-filter="hot">Hot ${hotItems.length}</button></div><small aria-live="polite" data-pulse-count>${items.length} briefings shown</small></div><div class="pulse-feed">${items.map(item=>pulseCard(item)).join('')}</div><div class="pulse-method"><article><span class="kicker">HOW CONTENT IS MADE</span><h2>Live facts, useful synthesis</h2><p>${esc(pulseData.scopeNote)} Titles, developers, dates, ranks, ratings and artwork come from Apple endpoints. Introductions, play descriptions and starting tips are automatically synthesized from store metadata and general genre patterns, then labelled on every card. Treat tips as a starting point and confirm version-sensitive details in game.</p></article><article><span class="kicker">VIDEO &amp; ENGAGEMENT</span><h2>Original creators stay visible</h2><p>Known games link to a specific YouTube video and name its creator. New or unfamiliar games use a clearly labelled YouTube search link until a relevant video is verified. Public view and like counts appear only when the optional YouTube API is configured; ${videosWithStats ? `${videosWithStats} videos in this edition include live public metrics.` : 'this edition does not claim unverified view or like counts.'}</p></article></div></section>`;
  const jsonLd=[{'@context':'https://schema.org','@type':'ItemList',name:`PlayScout Game Pulse ${pulseData.date}`,numberOfItems:items.length,itemListElement:items.map((item,index)=>({'@type':'ListItem',position:index+1,url:absolute(`/game-pulse/#${item.id}`),name:item.name,description:item.intro}))}];
  return layout({title:'Daily Game Pulse: new and trending iPhone games',description:'Daily briefings for three new US iOS games and three current grossing leaders, with gameplay introductions, starting tips, artwork and creator video links.',route:'/game-pulse/',active:'Game Pulse',body,jsonLd});
}

