function searchPage(){
  const index=[...games.map(x=>({type:'Game hub',title:x.name,text:`${x.genre} ${x.summary}`,url:href(`/games/${x.slug}/`)})),...pulseData.items.map(x=>({type:x.kind==='hot'?'Trending briefing':'New game briefing',title:x.name,text:`${x.developer} ${x.genre} ${x.intro} ${x.playStyle} ${x.tips.join(' ')}`,url:`${href('/game-pulse/')}#${x.id}`})),...guides.map(x=>({type:'Guide',title:x.title,text:x.dek,url:href(`/guides/${x.slug}/`)})),...news.map(x=>({type:'News',title:x.title,text:x.dek,url:href(`/news/${x.slug}/`)})),...discoveryData.giveaways.entries.map(x=>({type:'Live giveaway',title:x.title,text:`${x.platforms.join(' ')} ${x.description}`,url:x.sourceUrl})),...discoveryData.freeGames.entries.map(x=>({type:'Free-to-play game',title:x.title,text:`${x.platform} ${x.genre} ${x.description}`,url:x.sourceUrl}))];
  const body=`${pageHero('SITE SEARCH','Find a game or answer','Search Game Pulse briefings, game hubs, guides, news, live giveaways and the free-to-play catalog.')}<section class="shell search-page"><form role="search" action="${href('/search/')}" method="get"><label for="q">Search PlayScout</label><div><input id="q" name="q" type="search" placeholder="Try “strategy tips” or a game name" autocomplete="off" data-site-search><button type="submit">Search</button></div></form><p class="result-count" aria-live="polite" data-search-count>Start typing to search ${index.length} entries.</p><div class="search-results" data-search-results></div><noscript><p>JavaScript is required for preview search. Use the navigation above or the <a href="${href('/sitemap.xml')}">XML sitemap</a>.</p></noscript><script type="application/json" id="search-index">${JSON.stringify(index)}</script></section>`;
  return layout({title:'Search PlayScout',description:'Search PlayScout game hubs, mobile game guides and news.',route:'/search/',body,noindex:true});
}

function aboutPage(type){
  const isSources=type==='sources'; const title=isSources?'Sources and ranking methodology':'Editorial and player contribution policy';
  const body=`${pageHero('ABOUT PLAYSCOUT',title,isSources?'How rankings, changing facts, screenshots and external videos should be collected and verified.':'How editors turn official updates and player experience into useful, accountable game help.')}<div class="shell prose-layout"><article class="prose">${isSources?`<h2>Source hierarchy</h2><p>Production facts should prefer official store APIs, publisher sites and first-party patch notes. Licensed chart providers may supply ranking snapshots. Reputable creator videos and player communities add experience, but they do not override first-party facts.</p><h2>Ranking fields</h2><p>Store rank, chart movement, editorial heat and recommendation status remain separate. Every changing value needs a region, platform, observed time and source record. The public page shows the last successful update and a stale state when a feed fails.</p><h2>Images and video</h2><p>Use publisher-approved press assets, store artwork through permitted APIs, owned screenshots, or licensed images. Keep YouTube videos on the original host using a specific video ID and link back to the creator.</p><h2>Collection workflow</h2><ol><li>Fetch only permitted fields at a respectful rate.</li><li>Store source URL, external ID and observation time.</li><li>Normalize game identity without erasing the source record.</li><li>Send meaningful changes to editorial review.</li><li>Publish only pages that meet the index-quality threshold.</li></ol>`:`<h2>Answer the player’s decision</h2><p>Every guide starts with the task a player wants to complete. The quick answer appears before background, and each step explains its resource cost, version assumptions and likely failure point.</p><h2>Labels carry meaning</h2><p><b>Official source</b> describes first-party material. <b>Editor verified</b> means an editor checked the claim. <b>Player tested</b> records hands-on experience. These labels cannot be added by an automated rewrite alone.</p><h2>Corrections and updates</h2><p>Material changes update the visible modified date and revision note. Expired codes and outdated strategies remain out of current lists. News pages link into durable game hubs so useful context survives after the headline ages.</p><h2>Community contributions</h2><p>Player tips need a game version, clear reproduction steps and permission to publish. Editors rewrite for clarity, preserve attribution and separate observation from confirmed game rules.</p>`}</article><aside>${sourceBox()}<section class="side-list"><span class="kicker">EXPLORE</span><h2>See the system</h2><a href="${href('/rankings/')}">Ranking tables</a><a href="${href('/guides/')}">Guide templates</a><a href="${href('/videos/')}">External video handling</a><a href="${href('/codes/')}">Code verification states</a></section></aside></div>`;
  return layout({title,description:isSources?'PlayScout source hierarchy, chart methodology, media rights and content collection workflow.':'PlayScout editorial standards, verification labels, corrections and player contribution policy.',route:`/about/${type}/`,body});
}

function sourceMethodPage(){
  const body=`${pageHero('ABOUT PLAYSCOUT','Sources and ranking methodology','How each live data feed is collected, scoped, attributed and refreshed without mixing platforms.')}<div class="shell prose-layout"><article class="prose"><h2>Three live sources, three distinct scopes</h2><p><b>Apple Marketing Tools RSS</b> supplies US iOS/iPadOS App Store Games ranks and release dates. It contains no Google Play ranks. <b>GamerPower</b> supplies active giveaways, game keys, loot and beta access across its labelled platforms, including selected Android and iOS offers. <b>FreeToGame</b> supplies a free-to-play PC and browser directory. PlayScout never combines these into a synthetic ranking.</p><h2>Daily Game Pulse</h2><p>Game Pulse is a derived briefing layer, not a fourth ranking provider. Each edition selects three recent Apple releases and three leaders from Apple’s US iOS grossing chart. Apple lookup metadata adds ratings, age labels and larger artwork. The introduction, play pattern and starting tips are automatically synthesized and explicitly labelled; version-sensitive claims still require editorial verification.</p><h2>Source links and update time</h2><p>Each live channel shows the provider, platform scope, last successful fetch and a link to the API or source page. GitHub Actions refreshes snapshots every six hours, so Game Pulse receives at least one new edition each day. A failed request keeps the last good snapshot instead of publishing an empty list.</p><div class="source-register"><a href="https://rss.marketingtools.apple.com/" target="_blank" rel="noopener noreferrer"><b>Apple Marketing Tools RSS</b><span>US · iOS/iPadOS · rankings and releases</span></a><a href="${href('/game-pulse/')}"><b>PlayScout Game Pulse</b><span>Derived daily briefing · 3 new + 3 hot · labelled synthesis</span></a><a href="${esc(discoveryData.giveaways.sourceUrl)}" target="_blank" rel="noopener noreferrer"><b>GamerPower API</b><span>Cross-platform · active offers · attribution required</span></a><a href="${esc(discoveryData.freeGames.sourceUrl)}" target="_blank" rel="noopener noreferrer"><b>FreeToGame API</b><span>PC/browser · free-to-play directory</span></a></div><h2>Ranking fields</h2><p>Store rank, chart movement, editorial heat and recommendation status remain separate. Every changing value needs a region, platform, observed time and source record. A future Android ranking requires a permitted Google Play data provider and will appear as its own chart.</p><h2>Images and video</h2><p>Store artwork comes from Apple’s permitted metadata endpoints. YouTube paths point to the original host and creator. A specific video is used only when matched to the game; otherwise the card says “Find videos” and opens YouTube search. Public engagement counts are shown only when obtained through the YouTube Data API.</p><h2>Collection workflow</h2><ol><li>Fetch only permitted fields at a respectful rate.</li><li>Store source URL, external ID, platform and observation time.</li><li>Normalize identity without erasing the original source record.</li><li>Keep rankings, offers and directories in separate data contracts.</li><li>Publish only pages that meet the index-quality threshold.</li></ol></article><aside>${sourceBox()}<section class="side-list"><span class="kicker">LIVE CHANNELS</span><h2>Inspect the data</h2><a href="${href('/game-pulse/')}">Daily Game Pulse</a><a href="${href('/rankings/')}">US iOS rankings</a><a href="${href('/new-games/')}">New iOS games</a><a href="${href('/giveaways/')}">Cross-platform giveaways</a><a href="${href('/free-games/')}">Free PC/browser games</a></section></aside></div>`;
  return layout({title:'Sources and ranking methodology',description:'PlayScout live data sources, platform scopes, attribution rules and six-hour update workflow for Apple, GamerPower and FreeToGame.',route:'/about/sources/',body});
}

function notFound(){
  const body=`<section class="not-found shell"><span class="error-code">404</span><span class="kicker">PAGE NOT FOUND</span><h1>That route is off the map</h1><p>Search for a game, return to the latest guides, or explore a working path below.</p><form action="${href('/search/')}" method="get"><input name="q" aria-label="Search PlayScout" placeholder="Search games and guides"><button>Search</button></form><div class="collection-grid"><a href="${href('/games/')}"><b>01</b><strong>Browse games</strong><span>12 complete game hubs</span></a><a href="${href('/rankings/')}"><b>02</b><strong>See rankings</strong><span>Free, paid and grossing views</span></a><a href="${href('/guides/')}"><b>03</b><strong>Read guides</strong><span>Step-by-step answers</span></a></div></section>`;
  return layout({title:'Page not found',description:'The requested PlayScout page could not be found.',route:'/404.html',body,noindex:true});
}

async function write(route, html){const file=routeFile(route);await mkdir(path.dirname(file),{recursive:true});await writeFile(file,html);}

await rm(out,{recursive:true,force:true});
await mkdir(out,{recursive:true});
await cp(path.join(root,'public'),out,{recursive:true});
await cp(path.join(root,'src','styles.css'),path.join(out,'styles.css'));
await cp(path.join(root,'src','app.js'),path.join(out,'app.js'));

const pages=[
  ['/',homePage()],['/games/',gamesPage()],['/rankings/',rankingsPage()],['/new-games/',releasesPage()],['/game-pulse/',gamePulsePage()],['/giveaways/',giveawaysPage()],['/free-games/',freeGamesPage()],['/guides/',channelPage('guides')],['/news/',channelPage('news')],['/videos/',videosPage()],['/codes/',codesPage()],['/search/',searchPage()],['/about/sources/',sourceMethodPage()],['/about/editorial-policy/',aboutPage('editorial-policy')]
];
for(const g of games) pages.push([`/games/${g.slug}/`,gamePage(g)]);
for(const item of guides) pages.push([`/guides/${item.slug}/`,articlePage(item,'guides')]);
for(const item of news) pages.push([`/news/${item.slug}/`,articlePage(item,'news')]);
for(const [route,html] of pages) await write(route,html);
await writeFile(path.join(out,'404.html'),notFound());

const indexed=pages.map(([route])=>route).filter(route=>route!='/search/');
const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${indexed.map(route=>`  <url><loc>${absolute(route)}</loc><lastmod>${buildDate}</lastmod></url>`).join('\n')}\n</urlset>\n`;
await writeFile(path.join(out,'sitemap.xml'),sitemap);
await writeFile(path.join(out,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${absolute('/sitemap.xml')}\n`);
await writeFile(path.join(out,'.nojekyll'),'');
await writeFile(path.join(out,'feed.xml'),`<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>${site.name}</title><link>${absolute('/')}</link><description>${site.description}</description>${news.map(n=>`<item><title>${esc(n.title)}</title><link>${absolute(`/news/${n.slug}/`)}</link><description>${esc(n.dek)}</description></item>`).join('')}</channel></rss>`);
console.log(`Built ${pages.length + 1} HTML pages in ${out}`);
